const SCV11AudioStaticInstruction *sc_v11_audio_epoch_lookup(uint16_t pc, uint8_t epoch) {
    size_t lo=0u, hi=sizeof(manifest)/sizeof(manifest[0]);
    while(lo<hi) {
        size_t mid=lo+(hi-lo)/2u;
        if(manifest[mid].pc<pc) lo=mid+1u; else hi=mid;
    }
    while(lo<sizeof(manifest)/sizeof(manifest[0]) && manifest[lo].pc==pc) {
        if(manifest[lo].epoch==epoch) return &manifest[lo];
        ++lo;
    }
    return NULL;
}
int sc_v11_audio_epoch_is_code_byte(uint16_t address, uint8_t epoch) {
    if(epoch!=SC_V11_AUDIO_EPOCH_SIMCITY_BOOT_TITLE) return 0;
    return (driver_code_bytes[address>>3] & (uint8_t)(1u<<(address&7u))) != 0u;
}
